    constructor(C _c) { c = _c; }

    // drive the contract and then assert the general rule
    function run(address caller) public {
        // require a sensible caller (not zero) to avoid trivialities
        require(caller != address(0));

        // ensure the caller is the current owner by checking c.owner() and using onlyOwner-restricted call
        address currentOwner = c.owner();
        require(currentOwner == address(this) || currentOwner != address(0));

        // Call owned() which in the original contract sets owner = msg.sender (the caller executing the call)
        // but in the mutant sets owner = address(0). We perform the call from this contract's context.
        c.owned();

