pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        // deploy test contract with constructor called by this test contract (msg.sender == address(this))
        deployer = address(this);
        c = new C(0, 0, 0);
    }

    // fuzz the burn amount; property: owner() must remain the deployer after calling burn(amount)
    function testFuzz_property(uint256 burnAmount) public {
        // keep burnAmount within a wide admissible domain (no tight restriction)
        // ensure deployer (this) has sufficient balance to perform burn when needed
        // The constructor gave totalSupply = 0 (since decimals=0 and initialSupply=0), so mint some tokens first
        // only owner can mint; msg.sender (this) is owner
        c.mintToken(address(this), 1);

        // Bound the burnAmount to be at most the balance we set (which is 1) so call will not revert due to insufficient balance
        uint256 amt = burnAmount % 2; // yields 0 or 1, keeps wide domain but admissible

        // call burn as owner (this)
        bool ok;
        try c.burn(amt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After burn returns (whether success or revert), owner must still be the deployer for the reference
        // We assert that owner() == deployer (this). This holds for the reference contract for all inputs;
        // the mutant that sets owner = address(0) in owned() can cause owner() to differ after burn for some inputs.
        assertTrue(c.owner() == deployer);
    }
}

