pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(uint256 burnAmount) public {
        // General rule: calling burn(amount) should not change owner() — owner remains the deployer for all inputs.
        // Keep burnAmount wide; restrict only to plausible domain: can't burn more than deployer's balance.
        uint256 deployerBalance = c.balanceOf(address(this));
        // bound burnAmount to [0, deployerBalance] so burn won't revert for being too large
        if (deployerBalance == 0) return; // nothing to test if no supply
        uint256 amt = burnAmount % (deployerBalance + 1);

        // call burn as the owner (this) — set up msg.sender to be deployer
        // ensure this contract is the owner (it is, since setUp deployed c)
        bool ok;
        try c.burn(amt) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: after attempting burn, owner must still be deployer (this)
        // We read c.owner() via public getter. The reference satisfies this for all inputs; the mutant will fail for some inputs.
        assertTrue(c.owner() == address(this));
    }
}

