pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // RULE: For any fuzzed burnAmount, when the deployer (owner) calls burn(burnAmount)
    // the public owner() getter remains equal to the deployer after the call.
    // The mutant replaces owned() implementation to set owner = address(0), so
    // for some inputs the mutant will cause owner() to become address(0) whereas
    // the reference keeps the deployer as owner. We fuzz the burn amount.
    function testFuzz_property(uint256 burnAmount) public {
        // keep domain wide but ensure burn call does not revert due to insufficient balance
        // the constructor set totalSupply = 0 and balanceOf[deployer] = 0; to allow burn to proceed
        // we need deployer to have balance >= burnAmount. So give deployer some funds.
        address deployer = address(this);
        // mint tokens to deployer via direct interaction: call mintToken as owner (setUp deployer is owner)
        // bound minted amount to a reasonable range so arithmetic stays valid
        uint256 mintAmount = bound(burnAmount, 0, type(uint256).max / 2);
        // ensure deployer has at least burnAmount by minting max(burnAmount,1)
        uint256 ensure = burnAmount > 0 ? burnAmount : 1;
        // mint enough to cover burn
        c.mintToken(deployer, ensure);

        // record owner before
        address ownerBefore = c.owner();

        // call burn as owner (this contract is the deployer/owner)
        bool ok;
        try c.burn(burnAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Exactly one assertion: reference C guarantees that for any burnAmount
        // when the owner calls burn, owner() remains equal to the deployer (address(this)).
        // The mutant that sets owner = address(0) in owned() will break this for some inputs.
        // We assert the property that owner() == ownerBefore whenever the burn call did not revert
        // (i.e., for admissible inputs where the call succeeded). This is a general rule reading c's getter.
        if (ok) {
            assertTrue(c.owner() == ownerBefore);
        } else {
            // if burn reverted, the property about postconditions when burn succeeds is not applicable; still allow test to pass
            assertTrue(true);
        }
    }
}

