pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }

    // Fuzzed parameters: caller will be the address attempting burn, and amount is the burn amount.
    // General rule: after any successful burn call (i.e., the call does not revert), the owner() getter remains the deployer address for the reference contract.
    function testFuzz_property(address caller, uint256 amount) public {
        // keep caller non-zero to be an admissible EOA
        vm.assume(caller != address(0));

        // Ensure the deployer (this contract) has sufficient balance to allow potential burns
        // c was constructed with initialSupply 0, so mint some tokens to this contract (owner) first
        // only owner can mint; the deployer of C is this test contract (setUp), so we can mint
        // mint a large amount so burns of any fuzzed amount can succeed when called by owner
        uint256 mintAmount = type(uint256).max / 4;
        c.mintToken(address(this), mintAmount);

        // If caller is the owner (this contract), we will call burn directly; otherwise the call should revert
        bool ok;
        if (caller == address(this)) {
            // call as the owner
            try c.burn(amount) {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            // non-owner attempting burn: will revert. Simulate caller as EOA
            vm.prank(caller);
            try c.burn(amount) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // Single assertion: if the burn call succeeded, owner() must still equal the deployer (this test contract)
        if (ok) {
            assertTrue(c.owner() == address(this));
        } else {
            // If burn did not succeed, we assert the property vacuously by checking owner is still the deployer
            // (reference contract never changes owner here), this avoids introducing a second assert.
            assertTrue(c.owner() == address(this));
        }
    }
}

