pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // Fuzzed params: an address that will attempt to call burn and a burn amount.
    // General rule: After any successful burn call, owner() is never address(0) in the correct contract.
    // The mutant can be made to violate this by having the true owner subsequently call owned(),
    // which in the mutant sets owner = address(0).
    function testFuzz_property(address caller, uint256 amount) public {
        // keep domain wide but avoid the zero address as the caller for clarity (EOA fuzz can be zero)
        // allow caller to be any address; owner (deployer) must be able to call burn to succeed, so
        // we will attempt burns both from deployer and arbitrary caller — but assertion is about owner not being zero
        vm.assume(caller != address(0));

        // Ensure deployer (this contract) has sufficient balance in c for burn to succeed when it calls
        // by default constructor gave balanceOf[deployer] == totalSupply == 0, so mint some tokens to deployer first
        // Only the owner (deployer) can mint/burn; deployer here is address(this) in setUp
        // Use the public owner (deployer) to mint to itself so burn can succeed
        // No vm cheats other than prank/deal are used

        // mint some tokens so that burn may succeed when called by the owner (this contract)
        // amount can be any value; to keep admissible domain wide, mint a large known amount
        // call mintToken as owner (owner is deployer/address(this))
        c.mintToken(address(this), type(uint256).max / 2);

        // 1) Option A: If the fuzzed caller equals the owner (deployer), do the burn as owner
        // 2) Otherwise, attempt burn from caller; it should revert (not allowed) so we only care about successful burns

        bool burnSucceeded = false;
        // If caller equals address(this) (the deployer/owner), perform burn as owner
        if (caller == address(this)) {
            // burn should succeed if amount <= balance, clamp amount to available balance
            uint256 maxBal = c.balanceOf(address(this));
            uint256 burnAmt = amount;
            if (burnAmt > maxBal) burnAmt = maxBal;
            // call burn as owner
            try c.burn(burnAmt) {
                burnSucceeded = true;
            } catch {
                burnSucceeded = false;
            }
        } else {
            // If caller is not owner, attempt burn; it should revert due to onlyOwner, but we still capture outcome
            vm.prank(caller);
            try c.burn(amount) {
                burnSucceeded = true;
            } catch {
                burnSucceeded = false;
            }
        }

        // If burn succeeded, in the correct contract owner() should never be address(0).
        // We assert that owner() != address(0) whenever burnSucceeded is true.
        // This is a single assertTrue reading c's public getter.
        if (burnSucceeded) {
            assertTrue(c.owner() != address(0));
        } else {
            // If burn did not succeed, the property vacuously holds; assert same form to keep single assertion active
            // We still assert owner() != address(0) because in the reference contract owner remains deployer (non-zero)
            assertTrue(c.owner() != address(0));
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: drive c and assert the distinguishing property
    function run(address caller) public {
        // precondition: caller must be a non-zero address
        require(caller != address(0));

        // Call owned() as if from `caller`. We cannot change msg.sender here,
        // so we simulate by requiring that the contract's current owner equals caller
        // before calling owned(); this ensures the onlyOwner modifier passes when the
        // contract's owner is caller. Read current owner.
        address beforeOwner = c.owner();
        require(beforeOwner == caller);

        // Now call owned() — this will set owner = payable(msg.sender) in the original
        // contract P, but set owner = payable(tx.origin) in mutant M. We invoke it
        // from this contract, so msg.sender == address(this) and tx.origin == caller.
        // To ensure onlyOwner passes, we need beforeOwner == address(this). But we cannot
        // change msg.sender. Therefore we instead arrange the call such that
        // msg.sender == caller by making this contract the caller through a
        // low-level call from caller. However test harnesses cannot perform that here,
        // so instead we use the observable difference: after calling owned() from
        // this contract, owner should equal address(this) in P but equal tx.origin (the
        // original external caller) in M. To make tx.origin different from address(this),
        // we require caller != address(this).

        require(caller != address(this));

        // Perform the call: c.owned() will execute with msg.sender == address(this)
        // and tx.origin == caller (the external account that invoked this test).
        c.owned();

        // Observe owner after the call
        address afterOwner = c.owner();

        // Assert the distinguishing property: owner equals msg.sender (the immediate caller)
        // In this context, the immediate caller of c.owned() was address(this), so on P we
        // expect afterOwner == address(this). On M, owned() sets owner = tx.origin, i.e. caller,
        // which differs because we required caller != address(this).
        assert(afterOwner == address(this));
    }

    // allow this contract to receive ether so that external caller can call run
    receive() external payable {}
}

