pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // fuzzed params: attackerAmount (amount to mint then burn) and seed to choose whether to route through a proxy
    function testFuzz_property(uint256 attackerAmount, uint256 routeViaProxy) public {
        // Keep domain wide but avoid trivial zero-only behaviour for amount by allowing zero too
        // routeViaProxy selects whether we call burn directly (routeViaProxy % 2 == 0) or via a proxy contract

        address deployer = address(this); // test contract deployed the C in setUp
        // initial owner should be the deployer (this test contract)
        address ownerBefore = c.owner();

        // Ensure ownerBefore equals deployer (sanity for reference contract)
        // We don't assert yet; we only make the scenario where mutation can change owner.

        // Make some funds for the owner so burn can succeed when called by owner
        // The contract's constructor set balanceOf[deployer] = totalSupply = 0, so mint some tokens to deployer
        // Only owner can mint; this test contract is the owner, so call mintToken
        uint256 mintAmount = attackerAmount + 1; // avoid minting zero when attackerAmount==0
        c.mintToken(deployer, mintAmount);

        bool ok;
        // If routeViaProxy is even -> call burn directly as owner (msg.sender == tx.origin == this)
        if (routeViaProxy % 2 == 0) {
            // direct call: msg.sender == tx.origin == this (the owner)
            try c.burn(attackerAmount) returns (bool res) { ok = res; } catch { ok = false; }
        } else {
            // route via a proxy contract: the proxy will call c.burn as an external call
            // Deploy a simple Proxy that will call burn on C. The proxy's tx.origin will be this test contract,
            // but msg.sender inside C during burn will be the proxy address. The mutant uses tx.origin in owned(),
            // so if owned() is called inside burn (via some path that calls owned()), the mutant may set owner to tx.origin,
            // which is this test contract, whereas msg.sender differs (proxy). This can expose the mutant behavior when
            // the contract erroneously assigns owner = tx.origin in owned().
            Proxy p = new Proxy(c);
            // Ensure the proxy has no special funds; it will call burn and be msg.sender inside C
            try p.callBurn(attackerAmount) returns (bool res) { ok = res; } catch { ok = false; }
        }

        // After the burn sequence, in the correct contract, owner should remain the original deployer (address(this)).
        // Read owner via public getter and assert equality. This single assertion must hold for reference C for all inputs,
        // and the mutant (which assigns owner = tx.origin inside owned()) can change owner when calls are proxied,
        // so the assertion will fail for some inputs when run against the mutant.
        assertTrue(c.owner() == ownerBefore);
    }
}

// Minimal proxy helper that calls burn on the target contract
contract Proxy {
    C target;
    constructor(C _target) {
        target = _target;
    }
    function callBurn(uint256 amount) external returns (bool) {
        return target.burn(amount);
    }
}

