pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address proxyAddr, uint256 burnAmount) public {
        // We fuzz a proxy address (will be used as salt to deploy a tiny proxy) and a burn amount.
        // Keep domain wide but avoid zero-address for deployment seed.
        vm.assume(proxyAddr != address(0));

        // Deploy an intermediate caller contract (AttackerProxy) whose address depends on fuzzed proxyAddr
        // by using create2 with salt derived from proxyAddr to satisfy the adversarial requirement.
        bytes memory initCode = type(AttackerProxy).creationCode;
        bytes32 salt = keccak256(abi.encodePacked(proxyAddr));
        address proxy;
        assembly {
            proxy := create2(0, add(initCode, 0x20), mload(initCode), salt)
        }
        // If create2 failed (very unlikely), skip this input
        vm.assume(proxy != address(0));

        // Fund the deployer (test contract) and the proxy so that calls can be made if needed
        vm.deal(address(this), 1 ether);
        vm.deal(proxy, 1 ether);

        // The contract C was deployed in setUp by this test contract, so this test contract is the owner.
        address ownerBefore = c.owner();

        // Call burn through the proxy. The proxy will call c.burn(burnAmount) on behalf of this contract.
        // The proxy's call will make msg.sender inside C be the proxy, and tx.origin be this test contract
        // for the reference implementation; the mutant using tx.origin in owned() could change owner.
        AttackerProxy(payable(proxy)).callBurn(address(c), burnAmount);

        // Exactly one assertion: in the correct contract, owner remains the deployer (this contract)
        // after the external proxied burn; mutant that assigns owner = tx.origin inside owned()
        // when owned() is invoked (onlyOwner) can alter owner to tx.origin, causing owner to differ.
        assertTrue(c.owner() == ownerBefore);
    }
}

// Minimal adversarial helper: a proxy that simply forwards a call to C.burn(amount)
contract AttackerProxy {
    constructor() {}
    function callBurn(address target, uint256 amount) public {
        // Forward call to target.burn(amount) with this contract as msg.sender
        // We use a low-level call to preserve the external call behavior.
        (bool ok, ) = target.call(abi.encodeWithSignature("burn(uint256)", amount));
        // ignore success/failure; the property concerns owner unchanged in reference impl
        // but we keep execution proceeding
    }
}

