contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // fuzzed params: intermediary address selector (as uint256) and burn amount
    function testFuzz_property(uint256 selector, uint256 burnAmount) public {
        // Keep selector in a reasonable range to pick among few deployed helpers
        uint256 idx = selector % 3;

        // Deploy three intermediary caller contracts that will call c.burn(amount)
        CallerA a = new CallerA(c);
        CallerB b = new CallerB(c);
        CallerC d = new CallerC(c);

        address intermediary;
        if (idx == 0) intermediary = address(a);
        else if (idx == 1) intermediary = address(b);
        else intermediary = address(d);

        // initial owner is the deployer (this test contract)
        address initialOwner = c.owner();

        // fund the intermediary so it can call burn if needed (burn requires onlyOwner, and owner is this test contract)
        // We will have this test contract call c.mintToken to give intermediary some balance (not necessary for burn but harmless)
        // Ensure this test contract remains owner and performs a call via intermediary that triggers owned() inside C if mutant present.

        // Have the intermediary call back into C.burn via a call from test contract (so msg.sender for C will be intermediary,
        // and tx.origin will be this test contract). To get msg.sender == intermediary while tx.origin == this contract,
        // we must have this contract call intermediary which then calls C.burn. We'll perform that by instructing intermediary
