        uint256 before = c.totalSupply();
        c.burn(v);
        uint256 after = c.totalSupply();
        // The original contract reduces totalSupply exactly by v, so (before - after) == v.
        // The mutant reduces by 2*v, violating this. Formulate as: before - after == v
        assert(before - after == v);
    }
    receive() external payable { }
}

